//! Fixed Current/qualified JSON20 projection, using original outer and node
//! codecs. This component does not stand in for History/Proof/Retention lanes.
use crate::{incremental_cognition_current_complete_v3::CompleteCognitionCurrentQualificationV3,incremental_cognition_history::CognitionHistoryCurrentSourceV1,incremental_cognition_json::CognitionJsonFieldV1,incremental_cognition_json_read,incremental_field_member::*,incremental_field_overlay::{WorldFieldOverlayContextV1,WorldFieldOverlayErrorV1,lookup},incremental_inventory_value_read::InventoryValueReader,incremental_json_records::{JsonAuxBuildV1,JsonChangeWorkV1,project_json_aux_paths_v1,advance_from_qualified_root,CognitionAuxJsonPatchV1},incremental_runtime_revocation::BusinessDiffProcessingWorkV1,incremental_world_rule_projection_delta::{Processing,spend}};
use oasis7_formal_protocol::{incremental_execution::{ExecutionTransaction,ExecutionFence,PreparedGuard,RootSetV1},incremental_state::MerkleNodeReader,incremental_value::{ValueNodeReader,ValueReadContext,ValueTreeError}};
use oasis7_proto::memory_budget::{MemoryBudget,MemoryClass,MemoryReservation,ReservedValue};
use std::{cell::RefCell,mem::size_of,sync::Arc};
fn bad()->ValueTreeError{ValueTreeError::Invalid("Cognition JSON20 projection source")}
fn limit()->ValueTreeError{ValueTreeError::ResourceLimited("Cognition JSON20 projection source")}
pub struct CognitionProjectionAuxWorkV1<'a>{pub pending_entries:&'a mut usize,pub json:&'a mut JsonChangeWorkV1,pub processing:&'a mut BusinessDiffProcessingWorkV1,pub controls_remaining:&'a mut u64}
struct Field{field:CognitionJsonFieldV1,present:bool,patches:JsonAuxBuildV1}
pub(crate) struct CognitionJsonProjectionRowsV1{fields:[Option<Field>;20],guard:PreparedGuard,roots:[u8;32],memory:MemoryBudget,_fee:MemoryReservation}
impl CognitionJsonProjectionRowsV1{
 pub(crate) fn validate<M:MerkleNodeReader>(&self,tx:&ExecutionTransaction<'_,M>,memory:&MemoryBudget,live:&ExecutionFence)->Result<(),WorldFieldOverlayErrorV1>{tx.validate_read_source_guard(&self.guard,live)?;if self.roots!=tx.parent_fence().parent_roots||!self.memory.same_pool(memory)||!self._fee.uses_budget(memory){return Err(bad().into())}Ok(())}
 pub(crate) fn visit_field_presence_with_work_v1<E>(&self,mut work:impl FnMut(u64,u64)->Result<(),E>,mut emit:impl FnMut(&'static str,Option<&'static str>,bool)->Result<(),E>)->Result<(),E>{for field in self.fields.iter().flatten(){work(1,0)?;let(root,member)=field.field.projection_envelope_path_v1();emit(root,member,field.present)?}Ok(())}
 pub(crate) fn visit_with_work_v1<E>(&self,mut work:impl FnMut(u64,u64)->Result<(),E>,mut emit:impl FnMut(&'static str,Option<&'static str>,&CognitionAuxJsonPatchV1)->Result<(),E>)->Result<(),E>{for field in self.fields.iter().flatten(){let(root,member)=field.field.projection_envelope_path_v1();for patch in &field.patches.patches{work(1,0)?;emit(root,member,patch)?}}Ok(())}
}
pub(super) struct PaidValues<'a,'b,R>{pub(super) source:&'a R,pub(super) p:&'a Processing<'b>}
impl<R:ValueNodeReader> ValueNodeReader for PaidValues<'_,'_,R>{fn read_node(&self,id:&[u8;32],max:usize,memory:&MemoryBudget,class:MemoryClass)->Result<Arc<ReservedValue<Vec<u8>>>,ValueTreeError>{spend(self.p,0,&mut||false)?;let raw=self.source.read_node(id,max,memory,class)?;let n=raw.len().checked_mul(16).and_then(|n|n.checked_add(128)).ok_or_else(limit)?;spend(self.p,n,&mut||false)?;Ok(raw)}}
#[derive(Clone,Copy)]pub(super) enum Scope{Current,QualifiedAll}
#[allow(clippy::too_many_arguments)]
fn capture<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(parent:&ReservedValue<CompleteCognitionCurrentQualificationV3>,roots:&RootSetV1,ctx:&mut WorldFieldOverlayContextV1<'_, '_, '_,M,R,E,C>,work:&mut CognitionProjectionAuxWorkV1<'_>,scope:Scope,live:&ExecutionFence)->Result<CognitionJsonProjectionRowsV1,WorldFieldOverlayErrorV1>{
 ctx.transaction.validate_guard(&ctx.transaction.guard(),live)?;if let Scope::QualifiedAll=scope{ctx.transaction.validate_bootstrap_read_only_v1(live)?}
 let memory=ctx.values.memory.clone();let p=Processing{bank:RefCell::new(&mut *work.processing)};let rootbytes=roots.state.iter().try_fold(roots.world_id.len()+4096,|n,root|n.checked_add(root.node_root.len()+128).ok_or_else(limit))?;spend(&p,rootbytes.checked_mul(16).ok_or_else(limit)?,&mut ctx.cancelled)?;parent.validate_binding(roots)?;let digest=roots.digest().map_err(|_|bad())?;
 if !parent.uses_budget(&memory)||parent.allocation_class()!=MemoryClass::Ordinary||ctx.values.class!=MemoryClass::Ordinary||!ctx.transaction.uses_budget(&memory)||ctx.transaction.parent_fence().parent_roots!=digest{return Err(bad().into())}
 spend(&p,size_of::<CognitionJsonProjectionRowsV1>()+4096,&mut ctx.cancelled)?;let fee=memory.reserve(size_of::<CognitionJsonProjectionRowsV1>()+4096,MemoryClass::Ordinary).map_err(ValueTreeError::Memory)?;
 let mut dirty=[false;20];
 if let Scope::Current=scope{let stop=RefCell::new(&mut ctx.cancelled);for root in &roots.state{ctx.transaction.visit_pending_writes(root.namespace,work.pending_entries,||spend(&p,0,&mut||(stop.borrow_mut())()).map_err(WorldFieldOverlayErrorV1::from),|key,before,after|{spend(&p,key.len(),&mut||(stop.borrow_mut())())?;if before==after||!key.starts_with(b"oasis7.iws.world-field-key.v1\0"){return Ok(())}let parsed=WorldFieldKeyV1::from_bytes(key).map_err(ValueTreeError::Invalid)?;for(index,field)in CognitionJsonFieldV1::ALL.iter().copied().enumerate(){let d=field.descriptor();if parsed.owner==d.owner&&parsed.name==d.name{if parsed.namespace!=root.namespace{return Err(bad().into())}dirty[index]=true;break}}Ok(())})?;}}else{dirty.fill(true)}
 let values=PaidValues{source:ctx.values.source,p:&p};let mut value_read=ValueReadContext{source:&values,memory:&memory,class:MemoryClass::Ordinary,io:&mut *ctx.values.io};
 let mut records=InventoryValueReader{values:&mut value_read,key_work:&mut *ctx.key_work,semantic_bytes:ctx.semantic_bytes,record_bytes:ctx.record_bytes,cancelled:&mut ctx.cancelled};let mut fields=std::array::from_fn(|_|None);
 for(index,field)in CognitionJsonFieldV1::ALL.iter().copied().enumerate(){spend(&p,0,&mut *records.cancelled)?;if !dirty[index]{continue}
  let old=match parent.history_source(){CognitionHistoryCurrentSourceV1::Enabled(q)=>q.json_entry(field,&digest)?.map(|q|q.body_root()),CognitionHistoryCurrentSourceV1::Disabled(_)=>None};
  let after=if let Scope::QualifiedAll=scope{None}else{let meta=WorldFieldKeyV1::new(field.descriptor(),WorldFieldRecordKindV1::Metadata,None).map_err(ValueTreeError::Invalid)?;let key=records.key(field.descriptor(),WorldFieldRecordKindV1::Entry,&())?;let a=lookup(ctx.transaction,&meta,&mut records,&mut ctx.take_state_error)?;let b=lookup(ctx.transaction,&key.0,&mut records,&mut ctx.take_state_error)?;match(a,b){(None,None)=>None,(Some(a),Some(b))=>{records.presence(&a,&meta,0)?;Some(incremental_cognition_json_read::outer(field,&key,&b,&mut records)?)},_=>return Err(bad().into())}};
  let selected=match scope{Scope::QualifiedAll=>old,Scope::Current=>after.as_deref()};
  if let Scope::Current=scope{if old==selected{continue}if let Some(after)=selected{if let Some(before)=old{advance_from_qualified_root(field.profile(),before,after,&mut records,work.json)?}else{crate::incremental_json_records::qualify_json_subtree_records_v1(field.profile(),after,&mut records,&mut work.json.json)?;}}}
  let mut patches=JsonAuxBuildV1::new(&memory)?;project_json_aux_paths_v1(field.profile(),if matches!(scope,Scope::Current){old}else{None},selected,&mut records,&mut work.json.json,&mut work.json.paths_remaining,&p,&mut patches)?;
  fields[index]=Some(Field{field,present:selected.is_some(),patches});
 }
 drop(records);drop(value_read);if let Some(error)=(ctx.take_state_error)(){return Err(error.into())}if let Scope::QualifiedAll=scope{ctx.transaction.validate_bootstrap_read_only_v1(live)?}
 Ok(CognitionJsonProjectionRowsV1{fields,guard:ctx.transaction.guard(),roots:digest,memory,_fee:fee})
}
pub(crate) fn capture_current_cognition_json_projection_v1<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(parent:&ReservedValue<CompleteCognitionCurrentQualificationV3>,roots:&RootSetV1,ctx:&mut WorldFieldOverlayContextV1<'_, '_, '_,M,R,E,C>,work:&mut CognitionProjectionAuxWorkV1<'_>,live:&ExecutionFence)->Result<CognitionJsonProjectionRowsV1,WorldFieldOverlayErrorV1>{capture(parent,roots,ctx,work,Scope::Current,live)}
pub(crate) fn capture_qualified_cognition_json_projection_v1<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(parent:&ReservedValue<CompleteCognitionCurrentQualificationV3>,roots:&RootSetV1,ctx:&mut WorldFieldOverlayContextV1<'_, '_, '_,M,R,E,C>,work:&mut CognitionProjectionAuxWorkV1<'_>,live:&ExecutionFence)->Result<CognitionJsonProjectionRowsV1,WorldFieldOverlayErrorV1>{capture(parent,roots,ctx,work,Scope::QualifiedAll,live)}
